.ds {
  --ds-token-space-space-2:var(--p-space-xs,8px);
  --ds-token-space-space-3:var(--p-space-sm,12px);
  --ds-token-space-space-4:var(--p-space-md,16px);
  --ds-token-space-space-6:var(--p-space-lg,24px);
  --ds-token-space-space-8:var(--p-space-xl,32px);
}
.ds .ds-token-space { display:grid; gap:6px; justify-items:start; }
.ds .ds-token-space i { display:block; height:10px; border-radius:5px; background:currentColor; }
.ds .ds-token-space [data-token="xs"] { width:calc(var(--ds-token-space-space-2) * 4); }
.ds .ds-token-space [data-token="sm"] { width:calc(var(--ds-token-space-space-3) * 4); }
.ds .ds-token-space [data-token="md"] { width:calc(var(--ds-token-space-space-4) * 4); }
.ds .ds-token-space [data-token="lg"] { width:calc(var(--ds-token-space-space-6) * 4); }
.ds .ds-token-space [data-token="xl"] { width:calc(var(--ds-token-space-space-8) * 4); }
